        "testata": "Il Manifesto",
        "lingua_originale": "it",
        "titolo_orig": "«Tristi tropici», il turismo neocoloniale",
        "testo_it": "Ambiente: turismo neocoloniale nei tropici espropria comunità costiere.",
        "priorita": "Bassa",
